11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "salutation",
22	        expression = "java(owner == null ? null : owner.getSalutation())")
23	    @Mapping(target = "displayName",
24	        expression = "java(owner == null ? null : owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(owner == null ? null : Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
27	    @Mapping(target = "telephoneDisplay",
28	        expression = "java(owner == null ? null : owner.getTelephoneDisplay())")
29	    @Mapping(target = "membershipPoints",
30	        expression = "java(owner == null ? null : owner.getMembershipPoints())")
31	    @Mapping(target = "membershipLevel",
32	        expression = "java(owner == null ? null : owner.getMembershipLevel())")
33	    @Mapping(target = "locality",
34	        expression = "java(owner == null ? null : org.springframework.samples.petclinic.mapper.LocalityLookup.regionFor(owner.getPostcode(), owner.getCity()))")
35	    @Mapping(target = "timezone",
36	        expression = "java(owner == null ? null : org.springframework.samples.petclinic.mapper.LocalityLookup.timezoneFor(owner.getPostcode(), owner.getCity()))")
37	    @Mapping(target = "contactPreference",
38	        expression = "java(owner == null ? null : owner.getContactPreference())")
39	    @Mapping(target = "ageBand",
40	        expression = "java(owner == null || owner.getAgeBand() == null ? null : org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.fromValue(owner.getAgeBand()))")
41	    @Mapping(target = "checkDigit",
42	        expression = "java(owner == null ? null : owner.getCheckDigit())")
43	    @Mapping(target = "fiscalYear",
44	        expression = "java(owner == null ? null : owner.getFiscalYear())")
45	    @Mapping(target = "identityKey",
46	        expression = "java(owner == null ? null : owner.getIdentityKey())")
47	    @Mapping(target = "selfLink",
48	        expression = "java(owner == null ? null : owner.getSelfLink())")
49	    OwnerDto toOwnerDto(Owner owner);
50	
51	    Owner toOwner(OwnerDto ownerDto);
52	
53	    @Mapping(target = "id", ignore = true)
54	    @Mapping(target = "pets", ignore = true)
55	    Owner toOwner(OwnerFieldsDto ownerDto);
56	
57	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
58	
59	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
60	
61	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
62	        OwnerPageDto ownerPageDto = new OwnerPageDto();
63	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
64	        ownerPageDto.setPage(ownerPage.getNumber());
65	        ownerPageDto.setSize(ownerPage.getSize());
66	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
67	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
68	        return ownerPageDto;
69	    }
70	}
