266	    /**
267	     * The owner's salutation, derived on read: the {@code title} and {@code lastName} separated
268	     * by a single space (e.g. {@code 'DR Franklin'}) when a title is present, or just the
269	     * {@code lastName} when no title is set.
270	     *
271	     * @return the salutation
272	     */
273	    @Transient
274	    public String getSalutation() {
275	        if (this.title != null && !this.title.isBlank()) {
276	            return this.title + " " + getLastName();
277	        }
278	        return getLastName();
279	    }
280	
281	    /**
282	     * The fiscal year that a date falls in, on a fiscal year that starts on 1 July: a date on or
283	     * after 1 July belongs to the fiscal year named for the following calendar year, and a date
284	     * before 1 July belongs to the fiscal year named for its own calendar year (e.g. both
285	     * 2026-07-01 and 2027-06-30 fall in fiscal year 2027).
286	     *
287	     * @param date the date to classify
288	     * @return the fiscal year number
289	     */
290	    public static int fiscalYearOf(LocalDate date) {
291	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
292	    }
293	
294	    /**
295	     * The owner's fiscal year, derived on read from the (business-day-adjusted)
296	     * {@code registrationDate} on a fiscal year that starts on 1 July, formatted {@code 'FY<YY>'}
297	     * where YY is the last two digits of the fiscal year, zero-padded (e.g. a registration date of
298	     * 2026-08-16 yields {@code 'FY27'}).
299	     *
300	     * @return the fiscal year, or {@code null} when no {@code registrationDate} is set
301	     */
302	    @Transient
303	    public String getFiscalYear() {
304	        if (this.registrationDate == null) {
305	            return null;
306	        }
307	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
308	    }
309	
310	    /**
311	     * The owner's membership points, derived on read from the fields assigned at create. Points
312	     * start at 0 and accumulate: 2 when an email is present, 1 when {@code namesakeCount} is 0,
313	     * 2 when the household has 3 or more members ({@code householdMemberCount} of 3 or more), and
314	     * 3 when the owner's tenure spans at least one elapsed fiscal year. Tenure is the number of
315	     * fiscal years (which start on 1 July) elapsed between the {@code registrationDate} and the
316	     * current date. Because a newly created owner has zero tenure, the tenure points are only
317	     * earned once the owner has entered a later fiscal year than the one they registered in.
318	     *
319	     * @return the membership points, 0 or more
320	     */
321	    @Transient
322	    public Integer getMembershipPoints() {
323	        int points = 0;
324	        if (this.email != null && !this.email.isBlank()) {
325	            points += 2;
326	        }
327	        if (this.namesakeCount != null && this.namesakeCount == 0) {
328	            points += 1;
329	        }
330	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
331	            points += 2;
332	        }
333	        if (this.registrationDate != null
334	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
335	            points += 3;
336	        }
337	        return points;
338	    }
339	
340	    /**
341	     * The owner's numeric membership level, derived on read by mapping {@link #getMembershipPoints}
342	     * to a level: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
343	     * Because a newly created owner has zero tenure, level 4 (which requires the tenure points) is
344	     * reached only once the owner has entered a later fiscal year than the one they registered in.
345	     *
346	     * <p>The points-derived level is finally capped by {@link #membershipLevelCap} when one was
347	     * assigned at create: a new owner joining an existing household without declaring it (see
348	     * {@code membershipLevelCap}) may not exceed one above the highest membership level already held
349	     * by an existing household member, so the returned level is the lesser of the derived level and
350	     * the cap. When no cap was assigned (a household's first member, or a declared member) the
351	     * derived level is returned unchanged.
352	     *
353	     * @return the membership level, from 1 to 4
354	     */
355	    @Transient
356	    public Integer getMembershipLevel() {
357	        int points = getMembershipPoints();
358	        int level;
359	        if (points >= 6) {
360	            level = 4;
361	        }
362	        else if (points >= 4) {
363	            level = 3;
364	        }
365	        else if (points >= 2) {
366	            level = 2;
367	        }
368	        else {
369	            level = 1;
370	        }
371	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
372	            return this.membershipLevelCap;
373	        }
374	        return level;
375	    }
376	
377	    /**
378	     * The owner's preferred contact channel, derived on read: {@code 'EMAIL'} when an
379	     * email address is present, otherwise {@code 'PHONE'}.
380	     *
381	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
382	     */
383	    @Transient
384	    public String getContactPreference() {
385	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
386	    }
387	
388	    /**
389	     * The owner's age band, derived on read from {@code birthDate} against the
390	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18, {@code 'ADULT'}
391	     * from 18 to 64, and {@code 'SENIOR'} at 65 or older. The age is the number of whole years
392	     * between the birth date and the registration date (falling back to the current date when no
393	     * registration date is set).
394	     *
395	     * @return the age band, or {@code null} when no {@code birthDate} is set
396	     */
397	    @Transient
398	    public String getAgeBand() {
399	        if (this.birthDate == null) {
400	            return null;
401	        }
402	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
403	        int age = Period.between(this.birthDate, reference).getYears();
404	        if (age < 18) {
405	            return "MINOR";
406	        }
407	        if (age < 65) {
408	            return "ADULT";
409	        }
410	        return "SENIOR";
411	    }
412	
413	    /**
414	     * The owner's check digit, derived on read: a single Luhn check digit computed over the
415	     * digits contained in the owner's {@code customerCode}.
416	     *
417	     * @return the Luhn check digit (0-9), or {@code null} when no customer code is assigned
418	     */
419	    @Transient
420	    public Integer getCheckDigit() {
421	        if (this.customerCode == null) {
422	            return null;
423	        }
424	        int sum = 0;
425	        boolean dbl = true;
426	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
427	            char c = this.customerCode.charAt(i);
428	            if (c < '0' || c > '9') {
429	                continue;
430	            }
431	            int d = c - '0';
432	            if (dbl) {
433	                d *= 2;
434	                if (d > 9) {
435	                    d -= 9;
436	                }
437	            }
438	            sum += d;
439	            dbl = !dbl;
440	        }
441	        return (10 - (sum % 10)) % 10;
442	    }
443	
444	    /**
445	     * The owner's stored E.164 {@code telephone} formatted for humans, derived on read: the
446	     * leading {@code '+'} and country code, a space, then the national digits grouped in threes
447	     * (e.g. {@code '+61 412 345 678'} for a stored {@code '+61412345678'}). The recognised
448	     * country codes are {@code '+61'} (Australia) and {@code '+1'} (NANP); any other prefix falls
449	     * back to a two-digit country code. The raw {@code telephone} is left in E.164 form.
450	     *
451	     * @return the human-formatted telephone, or the raw value when it is not in E.164 form
452	     */
453	    @Transient
454	    public String getTelephoneDisplay() {
455	        if (this.telephone == null || !this.telephone.startsWith("+")
456	                || !this.telephone.substring(1).matches("[0-9]+")) {
457	            return this.telephone;
458	        }
459	        String digits = this.telephone.substring(1);
460	        String countryCode;
461	        if (digits.startsWith("61")) {
462	            countryCode = "61";
463	        } else if (digits.startsWith("1")) {
464	            countryCode = "1";
465	        } else {
466	            countryCode = digits.length() > 2 ? digits.substring(0, 2) : digits;
467	        }
468	        String national = digits.substring(countryCode.length());
469	        StringBuilder display = new StringBuilder("+").append(countryCode);
470	        for (int i = 0; i < national.length(); i += 3) {
