427	    /**
428	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
429	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
430	     * and country code are present they are kept; otherwise country code {@code '+61'} is
431	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
432	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
433	     * the national-number length must match the country: {@code '+61'} (Australia) requires
434	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
435	     *
436	     * @param raw the submitted telephone, possibly {@code null}
437	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
438	     */
439	    private static String toE164(String raw) {
440	        if (raw == null) {
441	            return null;
442	        }
443	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
444	        String digits;
445	        if (cleaned.startsWith("+")) {
446	            digits = cleaned.substring(1);
447	        } else {
448	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
449	            digits = "61" + national;
450	        }
451	        if (!digits.matches("[0-9]{8,15}")) {
452	            return null;
453	        }
454	        if (digits.startsWith("61")) {
455	            // Australia: exactly 9 national digits after the '+61' country code.
456	            if (digits.length() - 2 != 9) {
457	                return null;
458	            }
459	        } else if (digits.startsWith("1")) {
460	            // NANP: exactly 10 national digits after the '+1' country code.
461	            if (digits.length() - 1 != 10) {
462	                return null;
463	            }
464	        }
465	        return "+" + digits;
466	    }
