848	                .digest(value.getBytes(StandardCharsets.UTF_8));
849	            StringBuilder sb = new StringBuilder(digest.length * 2);
850	            for (byte b : digest) {
851	                sb.append(String.format("%02x", b));
852	            }
853	            return sb.toString();
854	        }
