170	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
171	                        fieldError.getField(),
172	                        defaultMessage,
173	                        rejectedValue);
174	                    return new ValidationMessageDto(message)
175	                        .putAdditionalProperty("field", fieldError.getField())
176	                        .putAdditionalProperty("rejectedValue", rejectedValue)
177	                        .putAdditionalProperty("defaultMessage", defaultMessage);
178	                })
179	                .toList();
180	            logger.debug("Validation error at {} {}: {}",
181	                request.getMethod(),
182	                request.getRequestURI(),
183	                bindingResult.getFieldErrors());
184	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
185	            return ResponseEntity.status(status).body(detail);
186	        }
187	        return ResponseEntity.status(status).body(detail);
