637	    /**
638	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
639	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
640	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
641	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
642	     * every owner sharing a last name and postcode receives the same value, independent of create
643	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #identityKeyFor}
644	     * (which folds it into the identity key for duplicate detection) and
645	     * {@link #rejectDuplicateHousehold} (which blocks a second owner in the same household).
646	     *
647	     * @param lastName the owner's last name
648	     * @param postcode the owner's postcode, possibly {@code null}
649	     * @return the derived household id
650	     */
651	    private static String householdIdFor(String lastName, String postcode) {
652	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
653	        return sha256Hex(key).substring(0, 12);
654	    }
