656	    /**
657	     * Rejects a create whose computed {@code householdId} (derived from {@code lastName} and
658	     * {@code postcode}, see {@link #householdIdFor}) already belongs to an existing owner, unless
659	     * the request opts in via {@code sharesHousehold} or supplies its own {@code email}. Because
660	     * the household is keyed on {@code (lastName, postcode)}, a second owner sharing both is the
661	     * same household: it is rejected with a 409 as a household duplicate unless it declares
662	     * {@code sharesHousehold} (created as a declared household member) or carries an {@code email}
663	     * — a distinguishing identifier that marks it as a genuinely distinct member of the household
664	     * rather than a re-entry of an existing one, so it is admitted as an (undeclared) household
665	     * member whose membership level is capped (see {@link #assignMembershipLevelCap}). The scan is
666	     * taken over the existing owners before this one is persisted.
667	     *
668	     * @param ownerFieldsDto the submitted owner fields ({@code lastName}, {@code postcode} and the
669	     *                        already-normalized {@code email} set)
670	     * @throws DuplicateHouseholdException with a 409 status if the household already exists and the
671	     *                                     request neither opted in via {@code sharesHousehold} nor
672	     *                                     supplied an {@code email}
673	     */
674	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
675	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
676	            return;
677	        }
678	        String email = ownerFieldsDto.getEmail();
679	        if (email != null && !email.isBlank()) {
680	            return;
681	        }
682	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
683	        boolean duplicate = this.clinicService.findAllOwners().stream()
684	            .filter(existing -> !existing.isDeleted())
685	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
686	        if (duplicate) {
687	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
688	        }
689	    }
