691	    /**
692	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
693	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
694	     * after this create. Because {@code householdId} is derived from the owner's {@code lastName}
695	     * and {@code postcode} (see {@link #assignHouseholdId}), the count reflects every
696	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
697	     * The count is taken before this owner is persisted, so it is one more than the number of
698	     * existing household members.
699	     *
700	     * @param owner the owner being created (with its {@code householdId} already assigned)
701	     */
702	    private void assignHouseholdMemberCount(Owner owner) {
703	        String householdId = owner.getHouseholdId();
704	        long existing = this.clinicService.findAllOwners().stream()
705	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
706	            .count();
707	        owner.setHouseholdMemberCount((int) (existing + 1));
708	    }
